package com.chickencenter.ui.controllers;import java.util.HashMap;import java.util.Map;import java.util.function.Supplier;public class DataCache {    private static final Map<String, CacheEntry> cache = new HashMap<>();    private static final long CACHE_DURATION_MS = 30000;    public static <T> T get(String key, Supplier<T> supplier) {        CacheEntry entry = cache.get(key);        long now = System.currentTimeMillis();                if (entry != null && (now - entry.timestamp) < CACHE_DURATION_MS) {            return (T) entry.value;        }                T value = supplier.get();        cache.put(key, new CacheEntry(value, now));        return value;    }    public static void invalidate(String key) {        cache.remove(key);    }    public static void invalidateAll() {        cache.clear();    }    public static void invalidatePattern(String pattern) {        cache.keySet().stream()            .filter(k -> k.startsWith(pattern))            .forEach(cache::remove);    }    private static class CacheEntry {        final Object value;        final long timestamp;        CacheEntry(Object value, long timestamp) {            this.value = value;            this.timestamp = timestamp;        }    }}
